    public function run(): void
    {
        // disable foreign keys if necessary
        DB::statement('SET FOREIGN_KEY_CHECKS=0;');

        foreach (self::ACCOUNTS as $row) {
            financial_accounts::updateOrCreate(
                ['id' => $row['id']],
                $row + [
                    'account_type' => $row['account_type'] ?? null,
                    'other_table_FK' => null,
                    'orginal_id' => null,
                    'orginal_type' => null,
                    'orginal_supplier' => null,
                ]
            );
        }

        DB::statement('SET FOREIGN_KEY_CHECKS=1;');

        // عميل نقدي ومورد نقدي - واحد بس من كل نوع.
        $now = Carbon::now('Asia/Riyadh');
        $this->ensureCashCustomer($now);
        $this->ensureCashSupplier($now);
    }

    private function ensureCashCustomer(Carbon $now): void
    {
        $customer = customers::firstOrCreate(
            ['name' => 'عميل نقدي'],
            [
                'phone' => '0000000000',
                'notes' => 'عميل افتراضي للمبيعات النقدية (من غير عميل محدد).',
            ]
        );

        if ($customer->accounting_account_id ?? null) {
            return;
        }

        $nextAccountNumber = (int) (financial_accounts::where('parent_account_number', self::CUSTOMERS_ACCOUNT_ID)
            ->where('orginal_type', 1)
            ->max('account_number') ?? 0) + 1;

        $account = financial_accounts::create([
            'name' => $customer->name,
            'account_type' => 1,
            'parent_account_number' => self::CUSTOMERS_ACCOUNT_ID,
            'account_number' => $nextAccountNumber,
            'start_balance' => 0,
            'current_balance' => 0,
            'start_balance_status' => 3,
            'added_by' => Auth::id() ?? 1,
            'com_code' => 1,
            'date' => $now,
            'active' => 1,
            'is_parent' => 0,
            'orginal_id' => $customer->id,
            'orginal_type' => 1,
        ]);

        // check if customer table has accounting_account_id
        // to avoid migration error if not present
        if (\Illuminate\Support\Facades\Schema::hasColumn('customers', 'accounting_account_id')) {
            $customer->update(['accounting_account_id' => $account->id]);
        }
    }

    private function ensureCashSupplier(Carbon $now): void
    {
        $supplier = supllier::firstOrCreate(
            ['name' => 'مورد نقدي'],
            [
                'phone' => '0000000000',
                'location' => 'مقر افتراضي',
                'email' => 'cash@supplier.com',
                'comp_name' => 'مورد افتراضي',
                'In_debt' => 0,
                'opeing_blance' => 0,
            ]
        );

        $existingAccount = financial_accounts::where('orginal_type', 2)->where('orginal_id', $supplier->id)->first();
        if ($existingAccount) {
            return;
        }

        $nextAccountNumber = (int) (financial_accounts::where('parent_account_number', self::SUPPLIERS_ACCOUNT_ID)
            ->where('orginal_type', 2)
            ->max('account_number') ?? 0) + 1;

        financial_accounts::create([
            'name' => $supplier->name,
            'account_type' => 2,
            'parent_account_number' => self::SUPPLIERS_ACCOUNT_ID,
            'account_number' => $nextAccountNumber,
            'start_balance' => 0,
            'current_balance' => 0,
            'start_balance_status' => 3,
            'added_by' => Auth::id() ?? 1,
            'com_code' => 1,
            'date' => $now,
            'active' => 1,
            'is_parent' => 0,
            'orginal_id' => $supplier->id,
            'orginal_type' => 2,
        ]);
    }
